<?php

declare(strict_types=1);

use App\Models\PayrollEntry;
use App\Services\Payroll\PayslipPdfService;
use Carbon\Carbon;
use Tests\Accuracy\Payroll\FixtureError;
use Tests\Accuracy\Restated\PayslipPrint;
use Tests\Accuracy\Restated\RestatedEntries;

/*
 * PYR-RST-04, the payslip against the entry. For each restated case the
 * payroll case is built, the engine runs it, the payslip PDF of every entry is
 * generated by PayslipPdfService and READ AS TEXT out of the PDF (PdfText): the
 * rows and amounts the page prints. Each printed figure is compared with the
 * entry's own. The test implements no payslip rule and recomputes no figure.
 *
 * A difference between the page and the entry is a finding (findings.php), never
 * a reason to change a case or the output.
 */

it('prints on the payslip what the entry holds', function (array $restated): void {
    $id = $restated['id'];
    $allowanceNames = [];

    try {
        $made = RestatedEntries::run($restated['case']);
        $allowanceNames = array_keys($made['case']['org']['allowances'] ?? []);
        $compared = 0;
        $misses = [];
        $people = 0;
        $withOvertime = 0;

        $ids = array_map(static fn ($e): int => $e->id, $made['built']['employees']);
        foreach (PayrollEntry::query()->where('payroll_run_id', $made['run']->id)->orderBy('id')->get() as $entry) {
            $who = array_search($entry->employee_id, $ids, true);
            $pdf = app(PayslipPdfService::class)->generate($entry);
            $rows = PayslipPrint::rows($pdf);
            $figures = RestatedEntries::read($entry);
            $result = PayslipPrint::compare($rows, $figures, array_map('strval', $allowanceNames), "[{$id}] {$made['case']['id']} {$who}");
            $compared += $result['compared'];
            $misses = [...$misses, ...$result['misses']];
            $people++;
            $withOvertime += $figures['overtime_cents'] > 0 ? 1 : 0;
        }
    } catch (FixtureError $e) {
        test()->fail("[{$id}] ".$e->getMessage());
    } finally {
        Carbon::setTestNow();
    }

    expect($people)->toBeGreaterThan(0);
    fwrite(STDERR, "RESTATED {$id} {$restated['case']}: {$people} payslips read, {$compared} printed figures compared, {$withOvertime} with overtime
");

    RestatedEntries::settle($id, $misses, $compared);
})->with(fn (): array => array_map(static fn (array $case): array => [$case], array_filter(RestatedEntries::cases(), static fn (array $c): bool => str_starts_with($c['id'], 'GR-PAYSLIP-'))));
